ee:message.ee:set-payload:
%dw 2.0
import try from dw::Runtime
import * from modules::Adf
output application/json skipNullOn="everywhere"

var req = vars.request
var issueTypeCode = req.issueType default "SYSTEM_SETUP"
var projectKey = req.project default p('jira.defaults.project')
var issueTypeId = p('jira.issueTypes.' ++ issueTypeCode)
var webTemplateCopyValue = p('jira.options.webTemplateCopy.' ++ (req.webTemplateCopy default p('jira.defaults.webTemplateCopy')))
// Ticket owner: request may override, else the environment default; empty -> Jira decides (token user / project default)
var reporterAccountId = (req.reporterAccountId default p('jira.defaults.reporterAccountId')) default ""

// Jira Cloud requires rich-text fields in Atlassian Document Format: modules::Adf renders the description markup
// (bold / underline / bullets / line breaks / mailto, see the RAML) and the one-per-line Additional Users.

// Every field this API knows how to send, by canonical name -> { Jira field, value }
var candidates = {
  summary:               { field: "summary",     value: req.summary },
  description:           { field: "description", value: toAdf(req.description) },
  reporter:              { field: "reporter",    value: if (isEmpty(reporterAccountId)) null else { accountId: reporterAccountId } },
  labels:                { field: "labels",      value: req.labels },
  dueDate:               { field: "duedate",     value: req.dueDate },
  priority:              { field: "priority",    value: if (req.priority == null) null else { name: req.priority } },
  productionInstance:    { field: p('jira.fields.productionInstance'), value: req.productionInstance default p('jira.defaults.productionInstance') },
  modules:               { field: p('jira.fields.modules'),            value: req.modules default p('jira.defaults.modules') },
  webTemplateCopy:       { field: p('jira.fields.webTemplateCopy'),    value: { value: webTemplateCopyValue } },
  sfOpportunityId:       { field: p('jira.fields.sfOpportunityId'),    value: req.sfOpportunityId },
  sfAccountId:           { field: p('jira.fields.sfAccountId'),        value: req.sfAccountId },
  organizationName:      { field: p('jira.fields.organizationName'),   value: req.organizationName },
  primaryContactName:    { field: p('jira.fields.primaryContactName'),    value: req.primaryContact.name },
  primaryContactEmail:   { field: p('jira.fields.primaryContactEmail'),   value: req.primaryContact.email },
  technicalContactName:  { field: p('jira.fields.technicalContactName'),  value: req.technicalContact.name },
  technicalContactEmail: { field: p('jira.fields.technicalContactEmail'), value: req.technicalContact.email },
  // Requirements v3 (1 Oct 2026) System Setup fields; ids read from the NSSU/SETUP create screen on 3 Oct 2026
  implementationType:    { field: p('jira.fields.implementationType'),    value: if (req.implementationType == null) null else { value: req.implementationType } },
  operatingCountry:      { field: p('jira.fields.operatingCountry'),      value: req.operatingCountry },
  nteeCode:              { field: p('jira.fields.nteeCode'),              value: req.nteeCode },
  nteeDivision:          { field: p('jira.fields.nteeDivision'),          value: req.nteeDivision },
  nteeCategory:          { field: p('jira.fields.nteeCategory'),          value: req.nteeCategory },
  // Additional Users is a MULTI-LINE text field (schema textarea): Jira Cloud v3 takes ADF, not a string (ERR-0024, 8 Oct 2026).
  // One paragraph per line of the request value; absent when the request carries none.
  additionalUsers:       { field: p('jira.fields.additionalUsers'),       value: if (req.additionalUsers == null) null else adfLines(req.additionalUsers) }
}
// The issue type's CREATE SCREEN decides which of them are sent: Jira answers 400 for a field that is not on the screen.
// jira.screens.<TYPE> lists canonical names (config); no entry = send everything (the behaviour before Scenario 2).
var screenProp = try(() -> p('jira.screens.' ++ issueTypeCode))
var screen = if (screenProp.success and !isEmpty(trim((screenProp.result default "") as String)))
                 ((screenProp.result as String) splitBy ",") map trim($)
             else (keysOf(candidates) map ($ as String))
var onScreen = candidates filterObject ((v, k) -> (screen contains (k as String)) and v.value != null)
---
{
  fields: { project: { key: projectKey }, issuetype: { id: issueTypeId } }
          ++ (onScreen mapObject ((v, k) -> { (v.field): v.value }))
}

%dw 2.0
output application/json skipNullOn="everywhere"
---
vars.created ++ {
  assignee: if (isEmpty(vars.assigneeAccountId)) null else { accountId: vars.assigneeAccountId, assigned: vars.assigned }
}

%dw 2.0
import * from dw::core::Arrays
output application/json skipNullOn="everywhere"

var readyStatusId = p('jira.status.instanceReadyId')
var jiraDateFormat = "yyyy-MM-dd'T'HH:mm:ss.SSSZ"
// Jira writes "2026-09-19T13:52:25.162-0500" (offset without colon). DataWeave keeps the parsed format on output, and
// RFC 3339 consumers (our RAML `datetime`, salesforce-sys-api) reject it (ERR-0018). Normalise to UTC "…Z".
fun toDateTime(s) = if (s == null) null
    else (((s as DateTime { format: jiraDateFormat }) >> "UTC") as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'" })

// Histories whose items include a status change INTO the instance-ready status; take the latest.
var readyTransitions = (payload.changelog.histories default [])
    filter ((h) -> (h.items default []) some ((i) -> i.field == "status" and (i.to as String) == readyStatusId))
    orderBy ((h) -> h.created)
---
{
  key: payload.key,
  id:  payload.id,
  url: "https://" ++ p('jira.host') ++ "/browse/" ++ payload.key,
  project:   payload.fields.project.key,
  issueType: payload.fields.issuetype.name,
  summary:   payload.fields.summary,
  status: {
    id:       payload.fields.status.id,
    name:     payload.fields.status.name,
    category: payload.fields.status.statusCategory.key
  },
  systemReadyAt:  if (isEmpty(readyTransitions)) null else toDateTime(readyTransitions[-1].created),
  sfOpportunityId: payload.fields[p('jira.fields.sfOpportunityId')],
  created: toDateTime(payload.fields.created),
  updated: toDateTime(payload.fields.updated)
}

%dw 2.0
output application/json skipNullOn="everywhere"
var body = read(vars.rawBody, "application/json")
var statusItems = (body.changelog.items default []) filter ($.field == "status")
---
{
  eventType:     body.webhookEvent,
  issueKey:      body.issue.key,
  issueId:       body.issue.id,
  statusChanged: !isEmpty(statusItems),
  status: {
    id:       body.issue.fields.status.id,
    name:     body.issue.fields.status.name,
    category: body.issue.fields.status.statusCategory.key
  },
  previousStatus: if (isEmpty(statusItems)) null else { id: statusItems[0].from, name: statusItems[0].fromString },
  // Jira sends `timestamp` in epoch MILLISECONDS; DataWeave's default Number -> DateTime coercion assumes seconds (parking-lot bug, fixed 1 Oct 2026)
  changedAt:      if (body.timestamp != null) ((body.timestamp as Number) as DateTime { unit: "milliseconds" }) else now(),
  sfOpportunityId: body.issue.fields[p('jira.fields.sfOpportunityId')],
  url: "https://" ++ p('jira.host') ++ "/browse/" ++ (body.issue.key default "")
}
